<template><el-dialog v-model="opened" title="内容运营与分享 · 保存为新草稿" width="min(800px,calc(100vw - 32px))" append-to-body :close-on-click-modal="false" :before-close="close"><div v-loading="loading"><el-alert title="这里单独保存运营设置，不包含其他未提交表单；保存会生成新草稿修订，发布后才影响前台。" :closable="false"/><el-form v-if="state" label-width="105px" @submit.prevent><template v-if="kind!=='page'"><el-form-item label="标签"><el-select v-model="form.tagIds" multiple :multiple-limit="12" filterable remote :remote-method="searchTags" @visible-change="v=>v&&searchTags('')" style="width:100%" placeholder="输入标签名称搜索"><el-option v-for="t in tags" :key="t.tagId" :label="t.name" :value="t.tagId"/></el-select></el-form-item><el-form-item label="推荐内容"><el-switch v-model="form.featured"/><span class="help">首页内容区块可设置只显示推荐。</span></el-form-item><el-form-item label="置顶优先级"><el-input-number v-model="form.pinOrder" :min="0" :max="100000" :precision="0"/><span class="help">0为普通；数字越大越靠前。</span></el-form-item></template><el-form-item label="关联内容"><el-select v-model="form.relatedIds" multiple :multiple-limit="12" filterable remote :remote-method="searchContent" @visible-change="v=>v&&searchContent('')" style="width:100%" placeholder="搜索文章或产品标题"><el-option v-for="t in related" :key="t.contentId" :label="t.title" :value="t.contentId"/></el-select><span class="help">前台只显示当前公开且栏目有效的关联内容。</span></el-form-item><el-divider content-position="left">分享卡片</el-divider><el-form-item label="分享标题"><el-input v-model="form.shareTitle" maxlength="150" placeholder="留空跟随页面标题"/></el-form-item><el-form-item label="分享描述"><el-input v-model="form.shareDescription" maxlength="300" type="textarea" :rows="2" placeholder="留空跟随SEO描述/摘要"/></el-form-item><el-form-item label="分享封面"><AssetPicker v-model="form.shareAssetId"/><span class="help">留空跟随封面或站点Logo。</span></el-form-item><el-divider content-position="left">搜索结果样式预览</el-divider><div class="search-preview"><small>{{path}}</small><h3>{{state.seoTitle||state.title}}</h3><p>{{state.seoDescription||state.summary||'未填写描述'}}</p></div><el-divider content-position="left">分享文案预览</el-divider><div class="share-preview"><h3>{{form.shareTitle||state.seoTitle||state.title}}</h3><p>{{form.shareDescription||state.seoDescription||state.summary}}</p><small>预览仅示意排版；实际展示由搜索引擎及分享平台决定。</small></div></el-form></div><template #footer><el-button :disabled="busy" @click="close()">关闭</el-button><el-button type="primary" :loading="busy" :disabled="loading||!state" @click="save">保存运营草稿</el-button></template></el-dialog></template>
<script setup>
import {ref,computed,onBeforeUnmount,onDeactivated} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import auth from '@/plugins/auth'
import request from '@/utils/request'
import AssetPicker from './AssetPicker.vue'
const props=defineProps({kind:String}),emit=defineEmits(['changed']),opened=ref(false),loading=ref(false),busy=ref(false),state=ref(),form=ref({}),tags=ref([]),related=ref([]);let epoch=0,tagEpoch=0,relatedEpoch=0,snapshot=''
const path=computed(()=>state.value?(props.kind==='article'?'/news/':props.kind==='product'?'/products/':'/p/')+state.value.slug:'')
async function open(row){const ticket=++epoch;state.value=undefined;opened.value=true;loading.value=true;try{const r=await request({url:`/cms/${props.kind}/${row.contentId}/operations`});if(ticket!==epoch||!opened.value)return;state.value=r.data;form.value={tagIds:[],relatedIds:[],featured:false,pinOrder:0,shareTitle:'',shareDescription:'',shareAssetId:0,...r.data.settings};form.value.tagIds||=[];form.value.relatedIds||=[];tags.value=form.value.tags||[];related.value=form.value.relatedIds.map(id=>({contentId:id,title:'内容 #'+id}));snapshot=JSON.stringify(form.value)}finally{if(ticket===epoch)loading.value=false}}
async function searchTags(name){if(!auth.hasPermi('cms:tag:list'))return;const ticket=++tagEpoch;const r=await request({url:'/cms/tag/list',params:{name,status:'0',pageNum:1,pageSize:50}});if(ticket===tagEpoch&&opened.value)tags.value=[...new Map([...tags.value.filter(x=>form.value.tagIds.includes(x.tagId)),...r.rows].map(x=>[x.tagId,x])).values()]}
async function searchContent(title){const ticket=++relatedEpoch;const kinds=['article','product'].filter(k=>auth.hasPermi(`cms:${k}:list`));const results=await Promise.all(kinds.map(k=>request({url:`/cms/${k}/list`,params:{title,pageNum:1,pageSize:30}})));if(ticket===relatedEpoch&&opened.value)related.value=[...new Map([...related.value.filter(x=>form.value.relatedIds.includes(x.contentId)),...results.flatMap(x=>x.rows).filter(x=>x.contentId!==state.value.contentId)].map(x=>[x.contentId,x])).values()]}
async function save(){if(busy.value||!state.value)return;busy.value=true;try{const settings={...form.value};delete settings.tags;await request({url:`/cms/${props.kind}/${state.value.contentId}/operations`,method:'put',data:{version:state.value.version,settings},headers:{repeatSubmit:false}});opened.value=false;++epoch;emit('changed');ElMessage.success('运营设置已保存为新草稿，尚未发布')}finally{busy.value=false}}
async function close(done){if(busy.value)return;if(state.value&&JSON.stringify(form.value)!==snapshot){try{await ElMessageBox.confirm('运营设置尚未保存，确认关闭？','未保存提醒')}catch{return}};cleanup();if(typeof done==='function')done()}
function cleanup(){++epoch;++tagEpoch;++relatedEpoch;opened.value=false;state.value=undefined}onBeforeUnmount(cleanup);onDeactivated(cleanup);defineExpose({open,close:cleanup})
</script><style scoped>.help{color:#667;font-size:12px;margin-left:8px}.search-preview,.share-preview{border:1px solid #ddd;border-radius:6px;padding:14px;margin-bottom:16px}.search-preview h3{color:#2356a1;margin:6px 0}.search-preview p,.share-preview p{overflow-wrap:anywhere}.share-preview small{color:#667}</style>